import { memo } from "react";

const TextInput = ({value,setValue}:{value: string, setValue:any}) => {
    return (
      <input
        style={{
          backgroundColor: "transparent",
          marginBottom: 2,
          borderWidth: 0,
          borderStyle: "solid",
          borderBottomWidth:1,
          display:'flex',
          color: 'white'
        }}
        value={'39898'}
        onChange={(e)=>setValue(e)}
      />
    );
  };

  export default memo(TextInput);
